Here's an example C++ program to count the number of times a specific word appears in a text file:

```c++
#include <iostream>
#include <fstream>

using namespace std;

int main() {
    string filename, word;
    int count = 0;

    cout << "Enter the name of the file: ";
    cin >> filename;

    cout<< "Enter the word you want to search for: ";
    getline(cin, word);

    ifstream inputFile(filename);
    if (!inputFile) {
        cerr << "Error opening file: " << filename << endl;
        return 1;
    }

    while (inputFile >> count)) {
        if (count == word.length()) {
            break;
        }
    }

    inputFile.close();

    cout << word << " occurs " << count << " times in the file." << endl;

    return 0;
}
```

